def payload_bytes():
    raw = base64.b64decode(PAYLOAD_B64.encode("ascii"))
    if len(raw) != PAYLOAD_BYTES:
        raise SystemExit("payload length mismatch: %d != %d" % (len(raw), PAYLOAD_BYTES))
    digest = hashlib.sha256(raw).hexdigest()
    if digest != PAYLOAD_SHA256:
        raise SystemExit("payload sha256 mismatch: %s != %s" % (digest, PAYLOAD_SHA256))
    return raw


def open_archive():
    return zipfile.ZipFile(io.BytesIO(payload_bytes()), "r")


def verify_only():
    raw = payload_bytes()
    z = open_archive()
    names = z.namelist()
    if len(names) != ARCHIVE_ENTRIES:
        raise SystemExit("entry count mismatch: %d != %d" % (len(names), ARCHIVE_ENTRIES))
    bad = []
    for name in names:
        data = z.read(name)
        exp = INDEX.get(name)
        if exp is None:
            bad.append((name, "not in index"))
            continue
        if hashlib.sha256(data).hexdigest() != exp[0] or len(data) != exp[1]:
            bad.append((name, "digest/length mismatch"))
    if bad:
        for name, why in bad:
            sys.stderr.write("MISMATCH %s: %s\n" % (name, why))
        raise SystemExit("verify-only failed: %d mismatch(es)" % len(bad))
    print("verify-only OK: payload sha256=%s bytes=%d entries=%d" % (PAYLOAD_SHA256, PAYLOAD_BYTES, len(names)))
    return 0


def list_entries():
    z = open_archive()
    for name in z.namelist():
        info = z.getinfo(name)
        print("%10d  %s" % (info.file_size, name))
    print("total entries: %d" % len(z.namelist()))
    return 0


def extract(dest):
    raw = payload_bytes()
    z = open_archive()
    os.makedirs(dest, exist_ok=True)
    written = 0
    bad = []
    for name in z.namelist():
        data = z.read(name)
        exp = INDEX.get(name)
        if exp is None:
            bad.append((name, "not in index"))
            continue
        if hashlib.sha256(data).hexdigest() != exp[0] or len(data) != exp[1]:
            bad.append((name, "digest/length mismatch"))
            continue
        target = os.path.join(dest, *name.split("/"))
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with open(target, "wb") as f:
            f.write(data)
        written += 1
    if bad:
        for name, why in bad:
            sys.stderr.write("MISMATCH %s: %s\n" % (name, why))
        raise SystemExit("extraction failed: %d mismatch(es)" % len(bad))
    print("extracted %d/%d entries into %s" % (written, len(z.namelist()), os.path.abspath(dest)))
    print("payload sha256=%s bytes=%d" % (PAYLOAD_SHA256, PAYLOAD_BYTES))
    return 0


def main(argv=None):
    ap = argparse.ArgumentParser(description="deposon deliverable pack v2 self-extractor")
    ap.add_argument("--dest", default=DEFAULT_DEST, help="output directory")
    ap.add_argument("--verify-only", action="store_true", help="verify without writing")
    ap.add_argument("--list", action="store_true", help="list archive entries")
    args = ap.parse_args(argv)
    if args.list:
        return list_entries()
    if args.verify_only:
        return verify_only()
    return extract(args.dest)


if __name__ == "__main__":
    sys.exit(main())
